class WaterMeterSpec(BaseModel):
    """
    Metrology per OIML R49 / ISO 4064 terms. Q1 = Q3 / ratio_r.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    technology: Annotated[MeterTechnology, Field(title="MeterTechnology")]
    nominal_diameter_mm: Annotated[float, Field(gt=0.0)]
    q3_m3_per_h: Annotated[float, Field(gt=0.0)]
    ratio_r: Annotated[float, Field(gt=0.0)]
    accuracy_class: Annotated[MeterAccuracyClass, Field(title="MeterAccuracyClass")]
    scale_interval_l: Annotated[float, Field(gt=0.0)]
    source_ref: Annotated[str, Field(pattern="^DS-[0-9]{3}$", title="SourceRef")]
    """
    Reference to an entry in docs/DATA_SOURCES.md (e.g. DS-007).
    """


class WaterSystem(BaseModel):
    """
    Water supply as a tree rooted at the measuring meter. Pipes name their upstream element; fixtures and valves name the pipe they sit on. Whether a fixture is fed from the main or the roof tank is derived from the topology, never stored.
    """

    model_config = ConfigDict(
        extra="forbid",
    )
    meters: Annotated[list[WaterMeter], Field(min_length=1)]
    tanks: list[Tank]
    pipes: Annotated[list[Pipe], Field(min_length=1)]
    valves: list[Valve]
    fixtures: Annotated[list[Fixture], Field(min_length=1)]


